impl<'a, 'b> LockStreamflowV2Cpi<'a, 'b> {
    pub fn new(
        program: &'b solana_program::account_info::AccountInfo<'a>,
        accounts: LockStreamflowV2CpiAccounts<'a, 'b>,
        args: LockStreamflowV2InstructionArgs,
    ) -> Self {
        Self {
            __program: program,
            genesis_account: accounts.genesis_account,
            bucket: accounts.bucket,
            base_mint: accounts.base_mint,
            quote_mint: accounts.quote_mint,
            genesis_base_token_account: accounts.genesis_base_token_account,
            bucket_quote_token_account: accounts.bucket_quote_token_account,
            recipient: accounts.recipient,
            authority: accounts.authority,
            sender: accounts.sender,
            sender_token_account: accounts.sender_token_account,
            fee_quote_token_account: accounts.fee_quote_token_account,
            metadata: accounts.metadata,
            escrow_tokens: accounts.escrow_tokens,
            recipient_tokens: accounts.recipient_tokens,
            streamflow_treasury: accounts.streamflow_treasury,
            streamflow_treasury_tokens: accounts.streamflow_treasury_tokens,
            withdrawor: accounts.withdrawor,
            partner: accounts.partner,
            partner_tokens: accounts.partner_tokens,
            fee_oracle: accounts.fee_oracle,
            rent: accounts.rent,
            timelock_program: accounts.timelock_program,
            base_token_program: accounts.base_token_program,
            quote_token_program: accounts.quote_token_program,
            associated_token_program: accounts.associated_token_program,
            system_program: accounts.system_program,
            backend_signer: accounts.backend_signer,
            __args: args,
        }
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], &[])
    }
    #[inline(always)]
    pub fn invoke_with_remaining_accounts(
        &self,
        remaining_accounts: &[(
            &'b solana_program::account_info::AccountInfo<'a>,
            bool,
            bool,
        )],
    ) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], remaining_accounts)
    }
    #[inline(always)]
    pub fn invoke_signed(
        &self,
        signers_seeds: &[&[&[u8]]],
    ) -> solana_program::entrypoint::ProgramResult {
        self.invoke_signed_with_remaining_accounts(signers_seeds, &[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed_with_remaining_accounts(
        &self,
        signers_seeds: &[&[&[u8]]],
        remaining_accounts: &[(
            &'b solana_program::account_info::AccountInfo<'a>,
            bool,
            bool,
        )],
    ) -> solana_program::entrypoint::ProgramResult {
        let mut accounts = Vec::with_capacity(27 + remaining_accounts.len());
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.genesis_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.bucket.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.base_mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.quote_mint.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.genesis_base_token_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.bucket_quote_token_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.recipient.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.authority.key,
            true,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.sender.key,
            true,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.sender_token_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.fee_quote_token_account.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.metadata.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.escrow_tokens.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.recipient_tokens.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.streamflow_treasury.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.streamflow_treasury_tokens.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.withdrawor.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.partner.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new(
            *self.partner_tokens.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.fee_oracle.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.rent.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.timelock_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.base_token_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.quote_token_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.associated_token_program.key,
            false,
        ));
        accounts.push(solana_program::instruction::AccountMeta::new_readonly(
            *self.system_program.key,
            false,
        ));
        if let Some(backend_signer) = self.backend_signer {
            accounts.push(solana_program::instruction::AccountMeta::new_readonly(
                *backend_signer.key,
                true,
            ));
        } else {
            accounts.push(solana_program::instruction::AccountMeta::new_readonly(
                crate::GENESIS_PROGRAM_ID,
                false,
            ));
        }
        remaining_accounts.iter().for_each(|remaining_account| {
            accounts.push(solana_program::instruction::AccountMeta {
                pubkey: *remaining_account.0.key,
                is_writable: remaining_account.1,
                is_signer: remaining_account.2,
            })
        });
        let mut data = borsh::to_vec(&(LockStreamflowV2InstructionData::new())).unwrap();
        let mut args = borsh::to_vec(&self.__args).unwrap();
        data.append(&mut args);

        let instruction = solana_program::instruction::Instruction {
            program_id: crate::GENESIS_PROGRAM_ID,
            accounts,
            data,
        };
        let mut account_infos = Vec::with_capacity(27 + 1 + remaining_accounts.len());
        account_infos.push(self.__program.clone());
        account_infos.push(self.genesis_account.clone());
        account_infos.push(self.bucket.clone());
        account_infos.push(self.base_mint.clone());
        account_infos.push(self.quote_mint.clone());
        account_infos.push(self.genesis_base_token_account.clone());
        account_infos.push(self.bucket_quote_token_account.clone());
        account_infos.push(self.recipient.clone());
        account_infos.push(self.authority.clone());
        account_infos.push(self.sender.clone());
        account_infos.push(self.sender_token_account.clone());
        account_infos.push(self.fee_quote_token_account.clone());
        account_infos.push(self.metadata.clone());
        account_infos.push(self.escrow_tokens.clone());
        account_infos.push(self.recipient_tokens.clone());
        account_infos.push(self.streamflow_treasury.clone());
        account_infos.push(self.streamflow_treasury_tokens.clone());
        account_infos.push(self.withdrawor.clone());
        account_infos.push(self.partner.clone());
        account_infos.push(self.partner_tokens.clone());
        account_infos.push(self.fee_oracle.clone());
        account_infos.push(self.rent.clone());
        account_infos.push(self.timelock_program.clone());
        account_infos.push(self.base_token_program.clone());
        account_infos.push(self.quote_token_program.clone());
        account_infos.push(self.associated_token_program.clone());
        account_infos.push(self.system_program.clone());
        if let Some(backend_signer) = self.backend_signer {
            account_infos.push(backend_signer.clone());
        }
        remaining_accounts
            .iter()
            .for_each(|remaining_account| account_infos.push(remaining_account.0.clone()));

        if signers_seeds.is_empty() {
            solana_program::program::invoke(&instruction, &account_infos)
        } else {
            solana_program::program::invoke_signed(&instruction, &account_infos, signers_seeds)
        }
    }
}

/// Instruction builder for `LockStreamflowV2` via CPI.
///
/// ### Accounts:
///
///   0. `[]` genesis_account
///   1. `[writable]` bucket
///   2. `[]` base_mint
///   3. `[]` quote_mint
///   4. `[writable]` genesis_base_token_account
///   5. `[writable]` bucket_quote_token_account
///   6. `[writable]` recipient
///   7. `[writable, signer]` authority
///   8. `[writable, signer]` sender
///   9. `[writable]` sender_token_account
///   10. `[writable]` fee_quote_token_account
///   11. `[writable]` metadata
///   12. `[writable]` escrow_tokens
///   13. `[writable]` recipient_tokens
///   14. `[writable]` streamflow_treasury
///   15. `[writable]` streamflow_treasury_tokens
///   16. `[writable]` withdrawor
///   17. `[writable]` partner
///   18. `[writable]` partner_tokens
///   19. `[]` fee_oracle
///   20. `[]` rent
///   21. `[]` timelock_program
///   22. `[]` base_token_program
///   23. `[]` quote_token_program
///   24. `[]` associated_token_program
///   25. `[]` system_program
///   26. `[signer, optional]` backend_signer
pub struct LockStreamflowV2CpiBuilder<'a, 'b> {
    instruction: Box<LockStreamflowV2CpiBuilderInstruction<'a, 'b>>,
}

